class Solution:
    def rankTeams(self, votes: List[str]) -> str:
        m = len(votes[0])
        cnt = {ch: [0] * m for ch in votes[0]}
        for v in votes:
            for i, ch in enumerate(v):
                cnt[ch][i] += 1
        return ''.join(sorted(votes[0], key=lambda ch: ([-c for c in cnt[ch]], ch)))

