class Solution {
public:
    string rankTeams(vector<string>& votes) {
        int m = votes[0].size();
        vector<array<int,26>> cnt(26, array<int,26>{});
        for (auto& v : votes)
            for (int i = 0; i < m; i++)
                cnt[v[i]-'A'][i]++;
        string teams = votes[0];
        sort(teams.begin(), teams.end(), [&](char a, char b) {
            for (int i = 0; i < m; i++)
                if (cnt[a-'A'][i] != cnt[b-'A'][i])
                    return cnt[a-'A'][i] > cnt[b-'A'][i];
            return a < b;
        });
        return teams;
    }
};

