class Solution {
    public String rankTeams(String[] votes) {
        int m = votes[0].length();
        int[][] cnt = new int[26][m];
        for (String v : votes)
            for (int i = 0; i < m; i++)
                cnt[v.charAt(i) - 'A'][i]++;
        Character[] teams = new Character[m];
        for (int i = 0; i < m; i++) teams[i] = votes[0].charAt(i);
        Arrays.sort(teams, (a, b) -> {
            for (int i = 0; i < m; i++)
                if (cnt[a - 'A'][i] != cnt[b - 'A'][i])
                    return cnt[b - 'A'][i] - cnt[a - 'A'][i];
            return a - b;
        });
        StringBuilder sb = new StringBuilder();
        for (char c : teams) sb.append(c);
        return sb.toString();
    }
}

