class Solution {
public:
    string rankTeams(vector<string>& votes) {
        int n = votes.size(), m = votes[0].size();
        vector<vector<int>> cnt(26, vector<int>(m, 0));
        for (auto& v : votes)
            for (int i = 0; i < m; i++) cnt[v[i]-'A'][i]++;
        vector<pair<string,char>> enc;
        for (char ch : votes[0]) {
            string s;
            for (int i = 0; i < m; i++) {
                int val = n - cnt[ch-'A'][i];
                s += string(4 - to_string(val).size(), '0') + to_string(val);
            }
            enc.push_back({s, ch});
        }
        sort(enc.begin(), enc.end());
        string res;
        for (auto& p : enc) res += p.second;
        return res;
    }
};

