class Solution {
    public String rankTeams(String[] votes) {
        int n = votes.length, m = votes[0].length();
        int[][] cnt = new int[26][m];
        for (String v : votes)
            for (int i = 0; i < m; i++) cnt[v.charAt(i)-'A'][i]++;
        String[] enc = new String[m];
        for (int t = 0; t < m; t++) {
            char ch = votes[0].charAt(t);
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < m; i++)
                sb.append(String.format("%04d", n - cnt[ch-'A'][i]));
            enc[t] = sb.toString() + ch;
        }
        Arrays.sort(enc);
        StringBuilder res = new StringBuilder();
        for (String e : enc) res.append(e.charAt(e.length()-1));
        return res.toString();
    }
}

